// A compiled-in bitmap font: 128 glyphs of height rows, one byte a row, bit 0
// leftmost, so at most 8 pixels wide
struct RETRO_FontData {
	const unsigned char *data;
	int width;
	int height;
	const unsigned char *widths = NULL; // per-character advance; null means fixed-width
};

// A font loaded from a PCX: one horizontal strip of width-wide glyph cells,
// character firstcharacter in the first
struct RETRO_FontAsset {
	const char *filename;
	int width;
	int height;
	int firstcharacter = 32;
};

// A font normalized to one horizontal atlas of fixed-width glyph cells,
// character firstcharacter at cell 0, however it started out. widths holds
// the same optional per-character advance override as RETRO_FontData; null
// means every glyph advances by width.
struct RETRO_Font {
	RETRO_Image *atlas;
	int width;
	int height;
	int firstcharacter;
	const unsigned char *widths = NULL;
};

static const RETRO_FontData RETRO_FONT_VGA_8X8 = { &RETRO_FONT_VGA_8X8_DATA[0][0], 8, 8 };
static const RETRO_FontData RETRO_FONT_TOPAZ13_8X8 = { &RETRO_FONT_TOPAZ13_8X8_DATA[0][0], 8, 8 };
static const RETRO_FontData RETRO_FONT_TOPAZ30_8X8 = { &RETRO_FONT_TOPAZ30_8X8_DATA[0][0], 8, 8 };
static const RETRO_FontData RETRO_FONT_MINECRAFT_8X8 = { &RETRO_FONT_MINECRAFT_8X8_DATA[0][0], 8, 8, &RETRO_FONT_MINECRAFT_8X8_WIDTHS[0] };
static const RETRO_FontData RETRO_FONT_SMALL_5X6 = { &RETRO_FONT_SMALL_5X6_DATA[0][0], 5, 6 };

//
// Compiled-in fonts
//

inline RETRO_FontData RETRO_CurrentFont = RETRO_FONT_VGA_8X8;

inline void RETRO_SetFont(const RETRO_FontData &font)
{
	RETRO_CurrentFont = font;
}

// The current font's rows for a character, or null past 7-bit ASCII
inline const unsigned char *RETRO_Glyph(unsigned char character)
{
	if (character >= 128) {
		return NULL;
	}
	return RETRO_CurrentFont.data + character * RETRO_CurrentFont.height;
}

inline bool RETRO_GlyphPixel(const unsigned char *glyph, int x, int y)
{
	return glyph[y] & (1 << x);
}

inline int RETRO_CharWidth(const RETRO_FontData &font, unsigned char character)
{
	return (font.widths && character < 128) ? font.widths[character] : font.width;
}

inline int RETRO_CharWidth(unsigned char character)
{
	return RETRO_CharWidth(RETRO_CurrentFont, character);
}

inline void RETRO_PutChar(unsigned char character, int x, int y, unsigned char color)
{
	const unsigned char *glyph = RETRO_Glyph(character);
	if (glyph == NULL) {
		return;
	}

	for (int yy = 0; yy < RETRO_CurrentFont.height; yy++) {
		for (int xx = 0; xx < RETRO_CurrentFont.width; xx++) {
			if (RETRO_GlyphPixel(glyph, xx, yy)) {
				RETRO_PutPixel(x + xx, y + yy, color);
			}
		}
	}
}

// A newline starts the next line back at x, a pixel below the font's height
inline void RETRO_PutString(const char *text, int x, int y, unsigned char color)
{
	int left = x;
	while (*text != 0) {
		unsigned char character = *text++;
		if (character == '\n') {
			x = left;
			y += RETRO_CurrentFont.height + 1;
			continue;
		}
		RETRO_PutChar(character, x, y, color);
		x += RETRO_CharWidth(character);
	}
}

// A line of text's width in the current font: its characters' advances, so
// a font that leaves a gap column counts it
inline int RETRO_StringWidth(const char *text)
{
	int width = 0;
	for (; *text != 0; text++) {
		width += RETRO_CharWidth((unsigned char)*text);
	}
	return width;
}

//
// VGA text mode: a screen of 8×8 character cells, each one character and one
// attribute byte, attribute = background · 16 + foreground, both nibbles
// indexing the first 16 palette entries
//
struct RETRO_TextCell {
	unsigned char character;
	unsigned char attribute;
};

// The 16 text colors, in attribute order, as RETRO_PALETTE_VGA lays them out
enum {
	RETRO_TEXT_BLACK, RETRO_TEXT_BLUE, RETRO_TEXT_GREEN, RETRO_TEXT_CYAN,
	RETRO_TEXT_RED, RETRO_TEXT_MAGENTA, RETRO_TEXT_BROWN, RETRO_TEXT_LIGHTGRAY,
	RETRO_TEXT_DARKGRAY, RETRO_TEXT_LIGHTBLUE, RETRO_TEXT_LIGHTGREEN, RETRO_TEXT_LIGHTCYAN,
	RETRO_TEXT_LIGHTRED, RETRO_TEXT_LIGHTMAGENTA, RETRO_TEXT_YELLOW, RETRO_TEXT_WHITE
};

// The 8×8 glyph of a text-mode character. The compiled-in fonts stop at 7-bit
// ASCII, so the CP437 shade and full blocks, 176–178 and 219, come from the
// VGA font's own bits here, and the rest of the upper half is blank.
inline const unsigned char *RETRO_TextModeGlyph(unsigned char character)
{
	static const unsigned char Blocks[5][8] = {
		{ 0x22, 0x88, 0x22, 0x88, 0x22, 0x88, 0x22, 0x88 }, // ░
		{ 0x55, 0xaa, 0x55, 0xaa, 0x55, 0xaa, 0x55, 0xaa }, // ▒
		{ 0xdb, 0xee, 0xdb, 0x77, 0xdb, 0xee, 0xdb, 0x77 }, // ▓
		{ 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff }, // █
		{ 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00 }, // blank
	};

	if (character >= 176 && character <= 178) {
		return Blocks[character - 176];
	}
	if (character == 219) {
		return Blocks[3];
	}
	if (character >= 128) {
		return Blocks[4];
	}
	return RETRO_Glyph(character);
}

// Draw a columns × rows text screen from the top left: glyph bits take the
// foreground, the rest the background
inline void RETRO_DrawTextScreen(const RETRO_TextCell *cells, int columns = RETRO_WIDTH / 8, int rows = RETRO_HEIGHT / 8)
{
	unsigned char *buffer = RETRO_FrameBuffer();
	for (int row = 0; row < rows; row++) {
		for (int column = 0; column < columns; column++) {
			RETRO_TextCell cell = cells[row * columns + column];
			const unsigned char *glyph = RETRO_TextModeGlyph(cell.character);
			unsigned char foreground = cell.attribute & 15;
			unsigned char background = cell.attribute >> 4;
			for (int y = 0; y < 8; y++) {
				unsigned char *pixel = buffer + (row * 8 + y) * RETRO_WIDTH + column * 8;
				for (int x = 0; x < 8; x++) {
					pixel[x] = RETRO_GlyphPixel(glyph, x, y) ? foreground : background;
				}
			}
		}
	}
}

//
// Atlas fonts
//

// Normalize a compiled-in bitmap font into a RETRO_Font: a fresh atlas image
// covering all 128 character slots, one width-wide cell per code, unpacked
// from the source's 1-bit rows into 0/255 texels. Palette index 0 is black,
// 255 is white, and every other index is copied from the active palette.
inline RETRO_Font RETRO_LoadFont(const RETRO_FontData &font)
{
	const int glyphs = 128;

	RETRO_Image *atlas = RETRO_AllocateImage();
	atlas->width = font.width * glyphs;
	atlas->height = font.height;
	atlas->data = (unsigned char *)calloc(atlas->width * atlas->height, 1);
	if (atlas->data == NULL) {
		RETRO_RageQuit("Cannot allocate font atlas memory\n");
	}
	for (int color = 0; color < RETRO_COLORS; color++) {
		atlas->palette[color] = RETRO_GetColor(color);
	}
	atlas->palette[0] = RETRO_Palette{ 0, 0, 0 }; // background defaults to black
	atlas->palette[255] = RETRO_Palette{ 255, 255, 255 }; // set font pixels default to white, not whatever color 255 happened to be

	for (int character = 0; character < glyphs; character++) {
		const unsigned char *glyph = font.data + character * font.height;

		for (int y = 0; y < font.height; y++) {
			for (int x = 0; x < font.width; x++) {
				if (RETRO_GlyphPixel(glyph, x, y)) {
					atlas->data[y * atlas->width + character * font.width + x] = 255;
				}
			}
		}
	}

	return RETRO_Font{ atlas, font.width, font.height, 0, font.widths };
}

// Normalize a horizontal PCX font atlas into a RETRO_Font. The atlas is
// used as loaded, palette and all nonzero texel values preserved verbatim;
// index zero remains transparent.
inline RETRO_Font RETRO_LoadFont(const RETRO_FontAsset &font)
{
	RETRO_Image *atlas = RETRO_LoadImage(font.filename);
	return RETRO_Font{ atlas, font.width, font.height, font.firstcharacter, NULL };
}

// A character's advance. The RETRO_FontAsset form answers before the font is
// loaded, so a demo can switch its font between a PCX and a compiled-in one
inline int RETRO_CharWidth(const RETRO_FontAsset &font, unsigned char character)
{
	return font.width;
}

inline int RETRO_CharWidth(const RETRO_Font &font, unsigned char character)
{
	return (font.widths && character < 128) ? font.widths[character] : font.width;
}

// The atlas texel at (x, y) of a character's glyph cell, 0 (no ink) off the
// cell or off the atlas, so a caller need not bounds-check the glyph, a
// neighbor or the character itself.
inline unsigned char RETRO_FontTexel(const RETRO_Font &font, unsigned char character, int x, int y)
{
	int cell = (int)character - font.firstcharacter;
	int sourcex = cell * font.width + x;
	if (cell < 0 || x < 0 || x >= font.width || y < 0 || y >= font.height) {
		return 0;
	}
	if (sourcex >= font.atlas->width || y >= font.atlas->height) {
		return 0;
	}
	return font.atlas->data[y * font.atlas->width + sourcex];
}

// Pixel size of one line as RETRO_GenerateTextImage would pack it: each
// glyph advances by its character width plus spacing, then both are scaled.
inline int RETRO_TextLineWidth(const RETRO_Font &font, const char *line, int scale = 1, int spacing = 0)
{
	if (line == NULL) {
		return 0;
	}
	int linewidth = 0;
	for (const char *scan = line; *scan != 0; scan++) {
		linewidth += (RETRO_CharWidth(font, (unsigned char)*scan) + spacing) * scale;
	}
	return linewidth;
}

// Unpack an array of lines into an allocated 8-bit image, glyph after glyph
// in the order given, repeats and all. Each line is centered within the
// widest one. A null slot is an empty row. The loaded font's palette and
// all nonzero atlas texels are carried through unchanged; index zero
// remains transparent. spacing adds unscaled font pixels of gap after every
// glyph, including the last, so a caller can wrap the width the same way
// regardless of spacing.
inline RETRO_Image *RETRO_GenerateTextImage(const RETRO_Font &font, const char *const *lines, int rows, int scale = 1, int spacing = 0)
{
	int width = 0;
	for (int row = 0; row < rows; row++) {
		width = MAX(width, RETRO_TextLineWidth(font, lines[row], scale, spacing));
	}
	int height = font.height * scale * rows;

	RETRO_Image *image = RETRO_AllocateImage();
	image->width = width;
	image->height = height;
	image->data = (unsigned char *)calloc(width * height, 1);
	if (image->data == NULL) {
		RETRO_RageQuit("Cannot allocate text strip memory\n");
	}
	for (int color = 0; color < RETRO_COLORS; color++) {
		image->palette[color] = font.atlas->palette[color];
	}

	for (int row = 0; row < rows; row++) {
		if (lines[row] == NULL) {
			continue;
		}
		const char *line = lines[row];
		int linewidth = RETRO_TextLineWidth(font, line, scale, spacing);
		int cursor = (width - linewidth) / 2;
		int rowbase = row * font.height * scale;

		while (*line != 0) {
			unsigned char character = *line++;
			int copywidth = MIN(font.width, RETRO_CharWidth(font, character));
			for (int y = 0; y < font.height; y++) {
				for (int x = 0; x < copywidth; x++) {
					unsigned char color = RETRO_FontTexel(font, character, x, y);
					if (color == 0) {
						continue;
					}
					for (int yy = 0; yy < scale; yy++) {
						for (int xx = 0; xx < scale; xx++) {
							int destx = cursor + x * scale + xx;
							if (destx < 0 || destx >= width) {
								continue;
							}
							image->data[(rowbase + y * scale + yy) * width + destx] = color;
						}
					}
				}
			}
			cursor += (RETRO_CharWidth(font, character) + spacing) * scale;
		}
	}

	return image;
}

#endif
